const ctx = $('Call Context Gather').first().json || {};
const ct = ctx.current_task || {};
let pd = false; try { pd = $('Call PD Verifier').first().json.personal_data === true; } catch(e) {}
let wc = {}; try { wc = $('When Called').first().json || {}; } catch(e) {}
const OPERATOR_ID = '2521617';
const reviewer = (wc.reviewer_user_id || OPERATOR_ID).toString();
const tcomment = (wc.triggering_comment_text || '').toString();
const prompt = 'Czy to zadanie wymaga aktualnych informacji z internetu (ceny, biezace wydarzenia, kursy walut, specyfikacje produktow, swieze fakty spoza wiedzy modelu), aby je dobrze wykonac? Odpowiedz wylacznie jednym slowem: TAK lub NIE.\n\nZADANIE:\n' + (ct.name || '') + '\n' + (ct.description || '') + (tcomment ? ('\n\nWIADOMOSC UZYTKOWNIKA:\n' + tcomment) : '');
return [{ json: {
  prompt: prompt,
  model_override: pd ? 'haxe-haiku-4-5-bedrock' : 'haxe-haiku-4-5-direct',
  personal_data: pd,
  impact: ctx.impact || '',
  clickup_task_id: ct.id || '',
  triggered_by: wc.triggered_by || 'explicit_command',
  invocation_type: wc.invocation_type || 'explicit',
  caller_user_id: reviewer,
  process_type: ctx.process_type || ''
} }];

const ctx = $('Call Context Gather').first().json || {};
const ct = ctx.current_task || {};
let pd = false; try { pd = $('Call PD Verifier').first().json.personal_data === true; } catch(e) {}
let wc = {}; try { wc = $('When Called').first().json || {}; } catch(e) {}
const OPERATOR_ID = '2521617';
const reviewer = (wc.reviewer_user_id || OPERATOR_ID).toString();
let rr = null; try { const r = $('Lookup Research Routing').first().json; if (r && r.litellm_model) rr = r; } catch(e) {}
const litellm_model = rr ? rr.litellm_model : (pd ? 'haxe-sonnet-4-6-bedrock' : 'haxe-sonnet-4-6-direct');
const max_tokens = (rr && rr.max_tokens != null) ? Number(rr.max_tokens) : 4000;
const temperature = (rr && rr.temperature != null && rr.temperature !== '') ? Number(rr.temperature) : null;
let rp = null; try { const p = $('Lookup Research Params').first().json; if (p && p.max_research_rounds != null) rp = p; } catch(e) {}
const max_research_rounds = (rp && rp.max_research_rounds != null) ? Number(rp.max_research_rounds) : 3;
const tavily_max_results = (rp && rp.tavily_max_results != null) ? Number(rp.tavily_max_results) : 5;
const tcomment = (wc.triggering_comment_text || '').toString();
const userPrompt = 'Jestes asystentem researchu. Zbierz z internetu aktualne, zewnetrzne informacje potrzebne do wykonania ponizszego zadania (np. ceny, kursy, specyfikacje, biezace fakty). Wykonaj potrzebne wyszukiwania, a nastepnie zwroc ZWIEZLE ustalenia (fakty + liczby), bez wykonywania samego zadania. NIE umieszczaj w zapytaniach danych osobowych (nazwiska, e-maile, numery zamowien).\n\nZADANIE:\n' + (ct.name || '') + '\n' + (ct.description || '') + (tcomment ? ('\n\nWIADOMOSC UZYTKOWNIKA:\n' + tcomment) : '');
const messages = JSON.stringify([{ role: 'user', content: userPrompt }]);
return [{ json: {
  litellm_model: litellm_model,
  messages: messages,
  max_tokens: max_tokens,
  temperature: temperature,
  depth: 0,
  max_depth: max_research_rounds,
  acc_in: 0, acc_out: 0, acc_usd: 0, acc_searches: 0,
  sources: '[]',
  tavily_max_results: tavily_max_results,
  calls: '[]',
  clickup_task_id: ct.id || '',
  caller_user_id: reviewer,
  process_type: ctx.process_type || '',
  triggered_by: wc.triggered_by || 'explicit_command',
  invocation_type: wc.invocation_type || 'explicit',
  impact: ctx.impact || ''
} }];
